-- fdh-c-check: ip row count of CHT
-- GENERATED by scripts/export_rules.mjs from BKH Insight src/app/api/fdh/c-check/checks.ts - do not edit by hand
-- params (2, in order of the placeholders): start, end
-- returns n
WITH p AS (SELECT CAST(? AS DATE) AS s, CAST(? AS DATE) AS e) SELECT COUNT(*) AS n FROM p JOIN ipt a ON a.dchdate BETWEEN p.s AND p.e INNER JOIN an_stat ans ON ans.an = a.an INNER JOIN patient pt ON pt.hn = ans.hn;
